    },
    {
      "role": "user",
      "content": "Subject: {{input.start__output__subject}}\n\nBody:\n{{input.start__output__body}}",
      "contentTokens": []
    }
  ],
  "projectId": "e0681df0-74c8-4c0b-b64f-35c42828238b"
}

